        try:
            self.s.close()
        except Exception:
            pass


def frame(func, args):
    body = json.dumps({"m": func, "p": args}, separators=(",", ":"))
    return "~m~%d~m~%s" % (len(body), body)


def unframe(raw):
    return re.findall(r"~m~\d+~m~(\{.*?\})(?=~m~|\Z)", raw)


