                elif m in ("series_completed", "critical_error",
                           "symbol_error", "series_error"):
                    if m != "series_completed":
                        raise ProviderDenied("TradingView " + m + "; no alternate provider attempted")
                    done = True
    finally:
        ws.close()
    return [[k] + bars[k] for k in sorted(bars)]


